function passReward(lv){if(lv%10===0)return{t:'skin'};if(lv%5===0)return{t:'chest',r:'E'};if(lv%3===0)return{t:'chest',r:'R'};if(lv%2===0)return{t:'gems',n:15};return{t:'pup',k:['fifty','shield','skip'][lv%3]}}
const rewardText=r=>r.t==='skin'?'New ink':r.t==='chest'?`${RAR[r.r].n} reward`:r.t==='gems'?`${r.n} gems`:{fifty:'Remove-two assist',shield:'Shield assist',skip:'Skip assist'}[r.k];
